using web_core::json_escape;

static const char kHostname[] = "fm1hub";
static const char kMdnsName[] = "fm1hub.local";
static const char kSetupSsid[] = "fm1hub-setup";
static const char kTokenHeader[] = "X-Fm1hub-Token";

// ---------- State shared by the loop and the server task, under state_mutex ----------
static SemaphoreHandle_t state_mutex;
struct Lock {
  Lock() { xSemaphoreTake(state_mutex, portMAX_DELAY); }
  ~Lock() { xSemaphoreGive(state_mutex); }
};

enum class Net : uint8_t { Off, Connecting, Online };
static Net net = Net::Off;
static bool ap_on = false;
static char own_ip[16] = "", ap_ip[16] = "", ssid_now[33] = "";
static uint32_t ap_ip_u32 = 0;  // network byte order, for the via-hotspot check
static int8_t rssi = 0;
static char ap_pass[9] = "";

static UiSettings settings_now{}, settings_pending{};
static bool settings_dirty = false;

static web_core::Pairing pairing;
static web_core::TokenStore tokens;
static bool tokens_dirty = false;

static char creds_ssid[33], creds_pass[65];
static bool creds_pending = false, forget_pending = false;

static char scan_json[1024] = "[]";
static bool scan_wanted = false;

static UiFrame *frame_copy;   // latest published frame, in PSRAM
static uint32_t frame_seq = 0;

static web_core::MonitorRing<256> ring;  // USB task -> server task, lock-free

// ---------- Loop-only state ----------
static Preferences wifi_prefs, web_prefs;
static httpd_handle_t server = nullptr;
static DNSServer dns;
static bool mdns_on = false, joining_from_setup = false;
static uint32_t connect_started = 0, online_since = 0, last_drain = 0;
static volatile bool drain_queued = false;
static char saved_ssid[33], saved_pass[65];

// ---------- Request helpers (server task) ----------
static bool header(httpd_req_t *req, const char *name, char *out, size_t len) {
  const size_t n = httpd_req_get_hdr_value_len(req, name);
  if (n == 0 || n >= len) return false;
  return httpd_req_get_hdr_value_str(req, name, out, len) == ESP_OK;
}

static web_core::HostNames names_locked() { return {kMdnsName, own_ip, ap_ip}; }

// The local address the request came in on is the hotspot's.
static bool via_hotspot(httpd_req_t *req) {
  struct sockaddr_storage addr;
  socklen_t len = sizeof addr;
  if (getsockname(httpd_req_to_sockfd(req), reinterpret_cast<sockaddr *>(&addr), &len) != 0) return false;
  uint32_t ip = 0;
  if (addr.ss_family == AF_INET) {
    ip = reinterpret_cast<sockaddr_in *>(&addr)->sin_addr.s_addr;
  } else if (addr.ss_family == AF_INET6) {
    const sockaddr_in6 *a6 = reinterpret_cast<sockaddr_in6 *>(&addr);
    memcpy(&ip, &a6->sin6_addr.un.u32_addr[3], 4);  // IPv4-mapped
  }
  Lock l;
  return ap_on && ip == ap_ip_u32;
}

static esp_err_t redirect_to_setup(httpd_req_t *req) {
  char where[40];
  {
    Lock l;
    snprintf(where, sizeof where, "http://%s/setup", ap_ip);
  }
  httpd_resp_set_status(req, "302 Found");
  httpd_resp_set_hdr(req, "Location", where);
  return httpd_resp_send(req, nullptr, 0);
}

// Every handler starts here: a foreign Host gets nothing (DNS rebinding), or a
// redirect to the setup page when it came through the hotspot (captive portal).
static bool guard(httpd_req_t *req) {
  char host[64] = "";
  header(req, "Host", host, sizeof host);
  bool ok;
  {
    Lock l;
    ok = web_core::host_allowed(host, names_locked());
  }
  if (ok) return true;
  if (via_hotspot(req)) redirect_to_setup(req);
  else httpd_resp_send_err(req, HTTPD_403_FORBIDDEN, "unknown host");
  return false;
}

static bool paired(httpd_req_t *req) {
  char token[40] = "";
  header(req, kTokenHeader, token, sizeof token);
  Lock l;
  return tokens.check(token);
}

static bool read_body(httpd_req_t *req, char *out, size_t len) {
  if (req->content_len >= len) return false;
  size_t got = 0;
  while (got < req->content_len) {
    const int r = httpd_req_recv(req, out + got, req->content_len - got);
    if (r <= 0) return false;
    got += r;
  }
  out[got] = 0;
  return true;
}

static esp_err_t send_json(httpd_req_t *req, const char *json) {
  httpd_resp_set_type(req, "application/json");
  httpd_resp_set_hdr(req, "Cache-Control", "no-store");
  return httpd_resp_sendstr(req, json);
}

static esp_err_t send_error(httpd_req_t *req, const char *status, const char *message) {
  char body[96];
  snprintf(body, sizeof body, "{\"error\":\"%s\"}", message);
  httpd_resp_set_status(req, status);
  return send_json(req, body);
}

static esp_err_t send_page(httpd_req_t *req, const uint8_t *gz, size_t len) {
  httpd_resp_set_type(req, "text/html; charset=utf-8");
  httpd_resp_set_hdr(req, "Content-Encoding", "gzip");
  httpd_resp_set_hdr(req, "Cache-Control", "no-cache");
  return httpd_resp_send(req, reinterpret_cast<const char *>(gz), len);
}

// ---------- Status JSON (server task) ----------
static size_t status_json(char *out, size_t len) {
  static UiFrame f;  // server task only
  UiSettings s;
  char ip[16], ssid[33];
  Net n;
  bool ap;
  int8_t r;
  {
    Lock l;
    if (frame_copy) f = *frame_copy;
    s = settings_now;
    memcpy(ip, own_ip, sizeof ip);
    memcpy(ssid, ssid_now, sizeof ssid);
    n = net;
    ap = ap_on;
    r = rssi;
  }
  const midi_core::ChainView &v = f.view;
  char a[64], b[64], c[64];
  size_t k = snprintf(out, len,
                      "{\"t\":\"status\",\"uptime\":%lu,\"usb\":%u,\"chain\":[%d,%d,%d,%d,%d],\"first_broken\":%u,",
                      (unsigned long)f.snapshot.uptime_ms, f.snapshot.channels_used, (int)v.power, (int)v.hub,
                      (int)v.controllers, (int)v.router, (int)v.target, v.first_broken);
  if (v.has_problem) {
    json_escape(v.problem.line1, a, sizeof a);
    json_escape(v.problem.line2, b, sizeof b);
    k += snprintf(out + k, len - k, "\"problem\":[\"%s\",\"%s\"],", a, b);
  } else {
    k += snprintf(out + k, len - k, "\"problem\":null,");
  }
  json_escape(f.hub_detail, a, sizeof a);
  k += snprintf(out + k, len - k, "\"hub\":\"%s\",\"controllers\":[", a);
  for (int i = 0; i < f.controller_count && k < len; ++i) {
    json_escape(f.controllers[i].tag, a, sizeof a);
    json_escape(f.controllers[i].detail, b, sizeof b);
    k += snprintf(out + k, len - k, "%s{\"tag\":\"%s\",\"detail\":\"%s\",\"open\":%s,\"fresh\":%s}", i ? "," : "", a, b,
                  f.controllers[i].open ? "true" : "false", f.controllers[i].fresh ? "true" : "false");
  }
  k += snprintf(out + k, len - k, "],\"devices\":[");
  for (int i = 0; i < f.snapshot.device_count && k < len; ++i) {
    const midi_core::DeviceView &d = f.snapshot.devices[i];
    char tag[4];
    midi_core::make_tag(d.name, tag);
    json_escape(d.name, a, sizeof a);
    k += snprintf(out + k, len - k, "%s{\"addr\":%u,\"name\":\"%s\",\"tag\":\"%s\",\"role\":\"%s\",\"midi\":%s}",
                  i ? "," : "", d.address, a, tag, d.role == midi_core::Role::Target ? "target" : "controller",
                  d.midi_open ? "true" : "false");
  }
  json_escape(f.fm1_in, a, sizeof a);
  json_escape(f.fm1_own, b, sizeof b);
  json_escape(ssid, c, sizeof c);
  k += snprintf(out + k, len - k,
                "],\"fm1_in\":\"%s\",\"fm1_in_fresh\":%s,\"fm1_own\":\"%s\",\"sent\":%lu,\"blocked\":%lu,"
                "\"settings\":{\"text_size\":%u,\"typeface\":%u,\"wifi\":%u},"
                "\"net\":{\"state\":\"%s\",\"ip\":\"%s\",\"ssid\":\"%s\",\"rssi\":%d,\"setup\":%s},"
                "\"bench\":\"%s\",\"monitor_dropped\":%lu}",
                a, f.fm1_in_fresh ? "true" : "false", b, (unsigned long)f.sent, (unsigned long)f.blocked,
                s.text_size, s.typeface, s.wifi, n == Net::Online ? "online" : n == Net::Connecting ? "connecting" : "off",
                ip, c, r, ap ? "true" : "false", bench_mode_name(bench_running()), (unsigned long)ring.dropped());
  return k < len ? k : len - 1;
}

// ---------- Handlers (server task) ----------
static esp_err_t on_index(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  if (via_hotspot(req)) return send_page(req, kSetupHtmlGz, sizeof kSetupHtmlGz);
  return send_page(req, kIndexHtmlGz, sizeof kIndexHtmlGz);
}

static esp_err_t on_setup(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  return send_page(req, kSetupHtmlGz, sizeof kSetupHtmlGz);
}

static esp_err_t on_status(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  static char buf[2048];
  status_json(buf, sizeof buf);
  return send_json(req, buf);
}

static esp_err_t on_settings(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  if (!paired(req)) return send_error(req, "401 Unauthorized", "pair first");
  char body[160];
  if (!read_body(req, body, sizeof body)) return send_error(req, "400 Bad Request", "body");
  long v;
  {
    Lock l;
    UiSettings s = settings_dirty ? settings_pending : settings_now;
    if (web_core::json_int(body, "text_size", &v) && v >= 0 && v <= 2) s.text_size = v;
    if (web_core::json_int(body, "typeface", &v) && v >= 0 && v <= 1) s.typeface = v;
    if (web_core::json_int(body, "wifi", &v) && v >= 0 && v <= 1) s.wifi = v;
    settings_pending = s;
    settings_dirty = true;
  }
  return send_json(req, "{\"ok\":true}");
}

static esp_err_t on_pair_start(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  {
    Lock l;
    pairing.start(millis(), esp_random());
  }
  char body[48];
  snprintf(body, sizeof body, "{\"ok\":true,\"seconds\":%lu}", (unsigned long)(web_core::Pairing::kLifetimeMs / 1000));
  return send_json(req, body);
}

static esp_err_t on_pair(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  char body[96], pin[12] = "";
  if (!read_body(req, body, sizeof body)) return send_error(req, "400 Bad Request", "body");
  web_core::json_string(body, "pin", pin, sizeof pin);
  uint8_t token[web_core::kTokenBytes];
  web_core::PairResult r;
  {
    Lock l;
    r = pairing.submit(millis(), pin);
    if (r == web_core::PairResult::Ok) {
      esp_fill_random(token, sizeof token);
      tokens.add(token);
      tokens_dirty = true;
    }
  }
  switch (r) {
    case web_core::PairResult::Ok: {
      char hex[33], out[64];
      web_core::token_to_hex(token, hex);
      snprintf(out, sizeof out, "{\"token\":\"%s\"}", hex);
      return send_json(req, out);
    }
    case web_core::PairResult::Wrong: return send_error(req, "403 Forbidden", "wrong PIN");
    case web_core::PairResult::Locked: return send_error(req, "403 Forbidden", "too many tries; start again");
    case web_core::PairResult::Expired: return send_error(req, "403 Forbidden", "PIN expired; start again");
    default: return send_error(req, "409 Conflict", "no pairing open; start one");
  }
}

static esp_err_t on_wifi_scan(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  static char buf[sizeof scan_json];
  {
    Lock l;
    memcpy(buf, scan_json, sizeof buf);
    scan_wanted = true;
  }
  return send_json(req, buf);
}

// Joining a network: from the setup hotspot (its password is on the device's
// screen), or from the LAN with a paired token.
static esp_err_t on_wifi_join(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  if (!via_hotspot(req) && !paired(req)) return send_error(req, "401 Unauthorized", "pair first");
  char body[192], ssid[33] = "", pass[65] = "";
  if (!read_body(req, body, sizeof body)) return send_error(req, "400 Bad Request", "body");
  if (!web_core::json_string(body, "ssid", ssid, sizeof ssid) || !ssid[0])
    return send_error(req, "400 Bad Request", "ssid");
  web_core::json_string(body, "pass", pass, sizeof pass);
  {
    Lock l;
    memcpy(creds_ssid, ssid, sizeof creds_ssid);
    memcpy(creds_pass, pass, sizeof creds_pass);
    creds_pending = true;
  }
  return send_json(req, "{\"ok\":true,\"next\":\"http://fm1hub.local/\"}");
}

static esp_err_t on_wifi_forget(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  if (!paired(req)) return send_error(req, "401 Unauthorized", "pair first");
  {
    Lock l;
    forget_pending = true;
  }
  return send_json(req, "{\"ok\":true}");
}

static esp_err_t on_bench(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  static char buf[4096];
  bench_json(buf, sizeof buf);
  return send_json(req, buf);
}

// Spike only: starting a run is open on the LAN so the Mac can script it.
static esp_err_t on_bench_start(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  char query[64] = "", mode[16] = "", secs[8] = "60";
  httpd_req_get_url_query_str(req, query, sizeof query);
  httpd_query_key_value(query, "mode", mode, sizeof mode);
  httpd_query_key_value(query, "s", secs, sizeof secs);
  if (!bench_start(bench_mode_from(mode), atoi(secs))) return send_error(req, "409 Conflict", "busy or bad mode");
  return send_json(req, "{\"ok\":true}");
}

static esp_err_t on_bench_raw(httpd_req_t *req) {
  if (!guard(req)) return ESP_OK;
  char query[64] = "", mode[16] = "", kind[4] = "0";
  httpd_req_get_url_query_str(req, query, sizeof query);
  httpd_query_key_value(query, "mode", mode, sizeof mode);
  httpd_query_key_value(query, "kind", kind, sizeof kind);
  static char *buf = static_cast<char *>(heap_caps_malloc(48 * 1024, MALLOC_CAP_SPIRAM));
  if (!buf) return send_error(req, "500 Internal Server Error", "no memory");
  bench_raw_json(bench_mode_from(mode), atoi(kind), buf, 48 * 1024);
  return send_json(req, buf);
}

static esp_err_t on_ws(httpd_req_t *req) {
  if (req->method == HTTP_GET) {
    // The server has already answered the handshake (no pre-handshake hook in
    // this build), so a refused socket is closed rather than sent a 403.
    char origin[96], host[64] = "";
    const bool has_origin = header(req, "Origin", origin, sizeof origin);
    header(req, "Host", host, sizeof host);
    Lock l;
    const web_core::HostNames names = names_locked();
    const bool ok = web_core::host_allowed(host, names) && web_core::origin_allowed(has_origin ? origin : nullptr, names);
    return ok ? ESP_OK : ESP_FAIL;
  }
  // The page sends nothing that matters; read and discard.
  httpd_ws_frame_t frame{};
  if (httpd_ws_recv_frame(req, &frame, 0) != ESP_OK) return ESP_FAIL;
  if (frame.len > 0 && frame.len < 256) {
    uint8_t scratch[256];
    frame.payload = scratch;
    httpd_ws_recv_frame(req, &frame, frame.len);
  }
  return ESP_OK;
}

static esp_err_t on_not_found(httpd_req_t *req, httpd_err_code_t) {
  if (via_hotspot(req)) return redirect_to_setup(req);  // captive-portal probes
  httpd_resp_send_err(req, HTTPD_404_NOT_FOUND, "not found");
  return ESP_OK;
}

// ---------- WebSocket push (server task, queued from the loop) ----------
static void send_all(const int *fds, int n, const char *text, size_t len) {
  httpd_ws_frame_t frame{};
  frame.type = HTTPD_WS_TYPE_TEXT;
  frame.final = true;
  frame.payload = reinterpret_cast<uint8_t *>(const_cast<char *>(text));
  frame.len = len;
  for (int i = 0; i < n; ++i) httpd_ws_send_frame_async(server, fds[i], &frame);
}

static void drain(void *) {
  static char buf[4096];
  static uint32_t sent_seq = 0, last_status_ms = 0;
  drain_queued = false;
  if (!server) return;

  size_t count = 8;
  int clients[8], ws[8], n = 0;
  if (httpd_get_client_list(server, &count, clients) != ESP_OK) count = 0;
  for (size_t i = 0; i < count; ++i)
    if (httpd_ws_get_fd_info(server, clients[i]) == HTTPD_WS_CLIENT_WEBSOCKET) ws[n++] = clients[i];

  web_core::MonitorEvent e;
  if (n == 0) {
    while (ring.pop(e)) {}
    return;
  }

  size_t k = snprintf(buf, sizeof buf, "{\"t\":\"midi\",\"ev\":[");
  int events = 0;
  while (k + 48 < sizeof buf && ring.pop(e)) {
    const char mark[2] = {e.mark ? e.mark : ' ', 0};
    k += snprintf(buf + k, sizeof buf - k, "%s[%lu,%u,\"%s\",%u,%u,%u]", events ? "," : "", (unsigned long)e.at_ms,
                  e.address, mark[0] == '"' || mark[0] == '\\' ? "?" : mark, e.status, e.data1, e.data2);
    ++events;
  }
  if (events) {
    k += snprintf(buf + k, sizeof buf - k, "]}");
    send_all(ws, n, buf, k);
  }

  uint32_t seq;
  {
    Lock l;
    seq = frame_seq;
  }
  const uint32_t now = millis();
  if (seq != sent_seq && now - last_status_ms >= 250) {
    sent_seq = seq;
    last_status_ms = now;
    send_all(ws, n, buf, status_json(buf, sizeof buf));
  }
}

// ---------- Server and Wi-Fi control (loop) ----------
static void add(const char *uri, httpd_method_t method, esp_err_t (*fn)(httpd_req_t *), bool ws = false) {
  httpd_uri_t u{};
  u.uri = uri;
  u.method = method;
  u.handler = fn;
  u.is_websocket = ws;
  httpd_register_uri_handler(server, &u);
}

static void start_server() {
  if (server) return;
  httpd_config_t cfg = HTTPD_DEFAULT_CONFIG();
  cfg.core_id = 0;
  cfg.task_priority = 3;  // below the USB host tasks (5)
  cfg.stack_size = 8192;
  cfg.max_open_sockets = 7;
  cfg.max_uri_handlers = 16;
  cfg.lru_purge_enable = true;
  cfg.send_wait_timeout = 1;
  cfg.recv_wait_timeout = 2;
  if (httpd_start(&server, &cfg) != ESP_OK) {
    server = nullptr;
    return;
  }
  add("/", HTTP_GET, on_index);
  add("/setup", HTTP_GET, on_setup);
  add("/api/status", HTTP_GET, on_status);
  add("/api/settings", HTTP_POST, on_settings);
  add("/api/pair/start", HTTP_POST, on_pair_start);
  add("/api/pair", HTTP_POST, on_pair);
  add("/api/wifi/scan", HTTP_GET, on_wifi_scan);
  add("/api/wifi", HTTP_POST, on_wifi_join);
  add("/api/wifi/forget", HTTP_POST, on_wifi_forget);
  add("/api/bench", HTTP_GET, on_bench);
  add("/api/bench/start", HTTP_POST, on_bench_start);
  add("/api/bench/raw", HTTP_GET, on_bench_raw);
  add("/ws", HTTP_GET, on_ws, true);
  httpd_register_err_handler(server, HTTPD_404_NOT_FOUND, on_not_found);
}

static void stop_server() {
  if (!server) return;
  httpd_stop(server);
  server = nullptr;
}

static void set_ips() {
  Lock l;
  if (WiFi.status() == WL_CONNECTED) {
    strlcpy(own_ip, WiFi.localIP().toString().c_str(), sizeof own_ip);
    strlcpy(ssid_now, WiFi.SSID().c_str(), sizeof ssid_now);
    rssi = WiFi.RSSI();
  } else {
    own_ip[0] = ssid_now[0] = 0;
  }
  if (ap_on) {
    const IPAddress ip = WiFi.softAPIP();
    strlcpy(ap_ip, ip.toString().c_str(), sizeof ap_ip);
    ap_ip_u32 = static_cast<uint32_t>(ip);
  } else {
    ap_ip[0] = 0;
    ap_ip_u32 = 0;
  }
}

static void start_hotspot() {
  if (ap_on) return;
  snprintf(ap_pass, sizeof ap_pass, "%08lu", static_cast<unsigned long>(esp_random() % 100000000));
  WiFi.mode(saved_ssid[0] ? WIFI_AP_STA : WIFI_AP);
  WiFi.softAP(kSetupSsid, ap_pass);
  dns.start(53, "*", WiFi.softAPIP());
  ap_on = true;
  WiFi.scanNetworks(true);
  set_ips();
}

static void stop_hotspot() {
  if (!ap_on) return;
  dns.stop();
  WiFi.softAPdisconnect(true);
  WiFi.mode(WIFI_STA);
  ap_on = false;
  set_ips();
}

static void join(const char *ssid, const char *pass) {
  WiFi.begin(ssid, pass);
  connect_started = millis();
  net = Net::Connecting;
}

static void wifi_on() {
  WiFi.persistent(false);  // credentials live in our own NVS namespace
  WiFi.setHostname(kHostname);
  if (saved_ssid[0]) {
    WiFi.mode(WIFI_STA);
    join(saved_ssid, saved_pass);
  } else {
    net = Net::Connecting;
    start_hotspot();
  }
  start_server();
}

static void wifi_off() {
  stop_server();
  if (mdns_on) MDNS.end();
  mdns_on = false;
  if (ap_on) dns.stop();
  ap_on = false;
  WiFi.disconnect(true);
  WiFi.mode(WIFI_OFF);
  net = Net::Off;
  set_ips();
}

static void collect_scan() {
  const int found = WiFi.scanComplete();
  if (found < 0) return;
  char buf[sizeof scan_json], name[70];
  size_t k = snprintf(buf, sizeof buf, "[");
  for (int i = 0; i < found && k + 100 < sizeof buf; ++i) {
    if (WiFi.SSID(i).length() == 0) continue;
    json_escape(WiFi.SSID(i).c_str(), name, sizeof name);
    k += snprintf(buf + k, sizeof buf - k, "%s{\"ssid\":\"%s\",\"rssi\":%d,\"open\":%s}", k > 1 ? "," : "", name,
                  WiFi.RSSI(i), WiFi.encryptionType(i) == WIFI_AUTH_OPEN ? "true" : "false");
  }
  snprintf(buf + k, sizeof buf - k, "]");
  WiFi.scanDelete();
  Lock l;
  memcpy(scan_json, buf, sizeof scan_json);
}

void web_begin(const UiSettings &settings) {
  state_mutex = xSemaphoreCreateMutex();
  frame_copy = static_cast<UiFrame *>(heap_caps_calloc(1, sizeof(UiFrame), MALLOC_CAP_SPIRAM));
  settings_now = settings;
  wifi_prefs.begin("wifi", false);
  strlcpy(saved_ssid, wifi_prefs.getString("ssid", "").c_str(), sizeof saved_ssid);
  strlcpy(saved_pass, wifi_prefs.getString("pass", "").c_str(), sizeof saved_pass);
  web_prefs.begin("web", false);
  web_prefs.getBytes("tokens", &tokens, sizeof tokens);
  if (tokens.count > web_core::TokenStore::kMax) tokens.count = 0;
}

void web_loop(uint32_t now) {
  bool want_on, save_tokens = false, new_creds = false, forget = false, scan = false;
  {
    Lock l;
    want_on = settings_now.wifi && !bench_wants_wifi_off(now);
    std::swap(save_tokens, tokens_dirty);
    std::swap(new_creds, creds_pending);
    std::swap(forget, forget_pending);
    std::swap(scan, scan_wanted);
  }
  if (save_tokens) {
    web_core::TokenStore copy;
    {
      Lock l;
      copy = tokens;
    }
    web_prefs.putBytes("tokens", &copy, sizeof copy);
  }
  if (want_on && net == Net::Off) wifi_on();
  if (!want_on && net != Net::Off) wifi_off();
  if (net == Net::Off) return;

  if (new_creds) {
    {
      Lock l;
      memcpy(saved_ssid, creds_ssid, sizeof saved_ssid);
      memcpy(saved_pass, creds_pass, sizeof saved_pass);
    }
    wifi_prefs.putString("ssid", saved_ssid);
    wifi_prefs.putString("pass", saved_pass);
    if (ap_on) WiFi.mode(WIFI_AP_STA);
    joining_from_setup = ap_on;
    WiFi.disconnect();
    join(saved_ssid, saved_pass);
  }
  if (forget) {
    wifi_prefs.remove("ssid");
    wifi_prefs.remove("pass");
    saved_ssid[0] = saved_pass[0] = 0;
    WiFi.disconnect();
    start_hotspot();
  }
  if (ap_on) {
    dns.processNextRequest();
    if (scan && WiFi.scanComplete() != WIFI_SCAN_RUNNING) WiFi.scanNetworks(true);
    collect_scan();
  }

  const bool connected = WiFi.status() == WL_CONNECTED;
  if (connected && net != Net::Online) {
    net = Net::Online;
    online_since = now;
    if (!mdns_on && MDNS.begin(kHostname)) {
      MDNS.addService("http", "tcp", 80);
      mdns_on = true;
    }
    set_ips();
  } else if (!connected && net == Net::Online) {
    net = Net::Connecting;
    connect_started = now;
    if (mdns_on) MDNS.end();
    mdns_on = false;
    set_ips();
  }
  // Keep the hotspot a little after joining, so the phone can show the new address.
  if (connected && ap_on && joining_from_setup && now - online_since > 30000) {
    joining_from_setup = false;
    stop_hotspot();
  }
  if (connected && ap_on && !joining_from_setup && saved_ssid[0]) stop_hotspot();
  // A saved network that doesn't answer: open the hotspot too, keep trying.
  if (!connected && !ap_on && now - connect_started > 20000) start_hotspot();
  static uint32_t last_ips = 0;
  if (connected && now - last_ips > 5000) {  // refresh RSSI
    last_ips = now;
    set_ips();
  }

  if (server && !drain_queued && now - last_drain >= 50) {
    last_drain = now;
    drain_queued = true;
    if (httpd_queue_work(server, drain, nullptr) != ESP_OK) drain_queued = false;
  }
}

void web_settings_changed(const UiSettings &s) {
  Lock l;
  settings_now = s;
}

bool web_take_settings(UiSettings &out) {
  Lock l;
  if (!settings_dirty) return false;
  settings_dirty = false;
  out = settings_pending;
  settings_now = settings_pending;
  return true;
}

void web_frame(UiFrame &f) {
  {
    Lock l;
    const char *pin = pairing.pin(millis());
    if (pin[0]) {
      strlcpy(f.banner1, "Pair browser", sizeof f.banner1);
      snprintf(f.banner2, sizeof f.banner2, "%.3s %.3s", pin, pin + 3);
    }
    switch (net) {
      case Net::Off:
        strlcpy(f.net_line, "Off", sizeof f.net_line);
        break;
      case Net::Online:
        snprintf(f.net_line, sizeof f.net_line, "%s", kMdnsName);
        snprintf(f.net_line2, sizeof f.net_line2, "%s  %s", own_ip, ssid_now);
        break;
      case Net::Connecting:
        snprintf(f.net_line, sizeof f.net_line, saved_ssid[0] ? "Joining %s" : "No network saved", saved_ssid);
        break;
    }
    if (ap_on) {
      snprintf(f.net_line, sizeof f.net_line, "Join %s", kSetupSsid);
      snprintf(f.net_line2, sizeof f.net_line2, "password %s", ap_pass);
    }
    if (frame_copy) {
      *frame_copy = f;
      ++frame_seq;
    }
  }
}

void web_monitor(const web_core::MonitorEvent &e) { ring.push(e); }
